{"path": "/tmp/sv-e0839db9f7fa44878a155e93e539f986/Components/Pages/Catalog/CatalogFilters.razor", "file_text": "<div class="catalog-filters">
    <h2>Filters</h2>

    <div class="filter-section">
        <h3>Categories</h3>
        @if (Categories is not null)
        {
            @foreach (var category in Categories)
            {
                <label class="filter-checkbox">
                    <input type="checkbox"
                           checked="@IsSelected(category)"
                           @onchange="@(e => ToggleCategory(category, (bool)e.Value!))" />
                    @category
                </label>
            }
        }
    </div>

    <div class="filter-section">
        <h3>Price Range</h3>
        <label>
            Min:
            <input type="number" min="0" step="0.01"
                   value="@MinPrice"
                   @onchange="@(e => MinPrice = ParseDecimal(e.Value))" />
        </label>
        <label>
            Max:
            <input type="number" min="0" step="0.01"
                   value="@MaxPrice"
                   @onchange="@(e => MaxPrice = ParseDecimal(e.Value))" />
        </label>
    </div>

    <div class="filter-section">
        <label class="filter-checkbox">
            <input type="checkbox"
                   checked="@InStockOnly"
                   @onchange="@(e => InStockOnly = (bool)e.Value!)" />
            In Stock Only
        </label>
    </div>

    <div class="filter-actions">
        <button class="btn-apply" @onclick="ApplyFilters">Apply Filters</button>
        <button class="btn-clear" @onclick="ClearFilters">Clear Filters</button>
    </div>
</div>

@code {
    [Parameter]
    public List<string>? Categories { get; set; }

    [Parameter]
    public EventCallback<ProductFilterState> OnApply { get; set; }

    [Parameter]
    public EventCallback OnClear { get; set; }

    private List<string> _selectedCategories = new();
    private decimal? MinPrice;
    private decimal? MaxPrice;
    private bool InStockOnly;

    private bool IsSelected(string category) => _selectedCategories.Contains(category);

    private void ToggleCategory(string category, bool selected)
    {
        if (selected && !_selectedCategories.Contains(category))
            _selectedCategories.Add(category);
        else if (!selected)
            _selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        var state = new ProductFilterState(
            _selectedCategories.Count > 0 ? new List<string>(_selectedCategories) : null,
            MinPrice,
            MaxPrice,
            InStockOnly);
        await OnApply.InvokeAsync(state);
    }

    private async Task ClearFilters()
    {
        _selectedCategories.Clear();
        MinPrice = null;
        MaxPrice = null;
        InStockOnly = false;
        await OnClear.InvokeAsync();
    }

    private static decimal? ParseDecimal(object? value)
    {
        if (value is null || string.IsNullOrWhiteSpace(value.ToString()))
            return null;
        return decimal.TryParse(value.ToString(), out var result) ? result : null;
    }

    public record ProductFilterState(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
}
"}

{"path": "/tmp/sv-e0839db9f7fa44878a155e93e539f986/Components/Pages/Catalog/CatalogPagination.razor", "file_text": "<div class="catalog-pagination">
    <button class="btn-page" disabled="@(CurrentPage <= 1)" @onclick="PreviousPage">
        Previous
    </button>

    @for (int i = 1; i <= TotalPages; i++)
    {
        var pageNum = i;
        <button class="btn-page @(pageNum == CurrentPage ? "active" : "")"
                @onclick="@(() => GoToPage(pageNum))">
            @pageNum
        </button>
    }

    <button class="btn-page" disabled="@(CurrentPage >= TotalPages)" @onclick="NextPage">
        Next
    </button>
</div>

@code {
    [Parameter]
    public int CurrentPage { get; set; }

    [Parameter]
    public int TotalPages { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private async Task PreviousPage()
    {
        if (CurrentPage > 1)
            await OnPageChanged.InvokeAsync(CurrentPage - 1);
    }

    private async Task NextPage()
    {
        if (CurrentPage < TotalPages)
            await OnPageChanged.InvokeAsync(CurrentPage + 1);
    }

    private async Task GoToPage(int page)
    {
        await OnPageChanged.InvokeAsync(page);
    }
}
"}

