.product-name {
    font-size: 1rem;
    margin: 0 0 0.5rem;
}

.product-price {
    font-size: 1.1rem;
    font-weight: 600;
    color: #198754;
    margin: 0 0 0.4rem;
}

.product-rating {
    color: #ffc107;
    font-size: 1.1rem;
    margin-bottom: 0.5rem;
}

.badge-out-of-stock {
    display: inline-block;
    padding: 0.2rem 0.5rem;
    background-color: #dc3545;
    color: white;
    font-size: 0.75rem;
    border-radius: 4px;
    margin-bottom: 0.5rem;
}

.btn-add-to-cart {
    width: 100%;
    padding: 0.5rem;
    border: none;
    border-radius: 4px;
    background-color: #0d6efd;
    color: white;
    cursor: pointer;
