}

.btn-page:hover:not(:disabled) {
    background-color: #e9ecef;
}

.btn-page.active {
    background-color: #0d6efd;
    color: white;
    border-color: #0d6efd;
}

.btn-page:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* States */
.catalog-loading,
.catalog-empty,
